{
  "headline": "Micafungin is not on FDA's shortage list as of 2026-10-21; Corvale East has 13.3 days on hand of the 20 mg/mL presentation and 14.5 days of the 10 mg/mL presentation",
  "headline_cites": ["D5", "D1", "D3"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows micafungin is not listed as of 2026-10-21.",
      "cites": ["D5"]
    },
    {
      "text": "Corvale East holds 192 vials of micafungin 20 mg/mL, 5 mL with 13.3 days on hand at 14.4 vials per day.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale East holds 216 vials of micafungin 10 mg/mL, 5 mL with 14.5 days on hand at 14.9 vials per day.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale General holds 512 vials of the 20 mg/mL presentation with 31 days on hand and 486 vials of the 10 mg/mL presentation with 30.2 days on hand.",
      "cites": ["D2", "D4"]
    },
    {
      "text": "A label for micafungin names Zydus Lifesciences Limited as the registered plant (FEI 3013712903) with an OAI inspection ending 2024-04-23 and a Warning Letter dated 2024-08-29.",
      "cites": ["E9", "E7", "E8"]
    },
    {
      "text": "A Class III recall by Zydus Pharmaceuticals (USA) Inc. for micafungin 100 mg/vial was initiated 2024-07-02 for cross contamination.",
      "cites": ["E10"]
    },
    {
      "text": "Par Health, USA LLC posted a discontinuation of micafungin sodium injection on 2026-09-11.",
      "cites": ["E12"]
    },
    {
      "text": "The rule ranks buying from Baxter Healthcare Corporation as the best option; it is not on FDA's shortage list today and its label names no plant we could place.",
      "cites": ["D6"]
    }
  ]
}
